def main():
    out_bags = []
    seen = set()
    for order, b in enumerate(BAGS, 1):
        foods = []
        h = j = 0
        for r in b["foods"]:
            fid = f"{b['code'].lower()}_{r[0]}"
            assert fid not in seen, fid
            seen.add(fid)
            assert r[7] in "ABDE", (fid, r[7])
            if r[7] in "AB":
                h += 1
            else:
                j += 1
            foods.append([fid] + r[1:])
        assert len(foods) == 20 and h == 10 and j == 10, (b["id"], len(foods), h, j)
        out_bags.append({
            "id": b["id"], "order": order, "country": b["code"], "mint": None,
            "name": dict(zip(("en", "it", "pl"), b["name"])),
            "accessory": dict(zip(("en", "it", "pl"), b["accessory"][1])), "accessoryKind": b["accessory"][0],
            "fact": dict(zip(("en", "it", "pl"), b["fact"])),
            "palette": b["palette"], "stripes": b["stripes"], "bg": b["bg"],
            "logo": f"logos/{b['id']}.svg", "tokenLogoPng": f"PIKKO_TOKEN_LOGOS/PIKKO_{b['code']}_{b['id']}_1024.png",
            "foods": foods,
        })
    assert len(out_bags) == 24
    doc = {
        "version": "0.3",
        "date": "2026-10-04",
        "notes": [
            "24 country bags x 20 foods (10 healthy grade A/B + 10 'sometimes' grade D/E) = 480 foods. v0.3 adds Indonesia, Russia, Ukraine, Philippines (one per added language). Starter Bag in PIKKO-GAME-DESIGN.md section 8.",
            "Traditional sweets, fried street food and party dishes are 'sometimes foods', never 'bad' foods: present them with respect.",
            "kcal values are APPROXIMATE per typical portion and must be verified (USDA FoodData Central / CREA / IZZ / national tables) and reviewed by a paediatric nutritionist.",
            "Grades are the internal Pikko Score, not the official Nutri-Score.",
            "Polish names need native-speaker review. Local dish names are kept where they are the common name.",
            "Logos use colour palettes inspired by each country, not flags or national emblems (some countries restrict commercial use of flags).",
            "mint is null until the developer supplies the Pump.fun CA and it passes Token-2022 / extension / route verification.",
        ],
        "foodColumns": ["id", "en", "it", "pl", "kcal", "portionQty", "portionUnit", "grade", "category"],
        "categories": {"healthy": ["veg", "fruit", "protein", "grain", "legume", "nuts", "dairy", "water"],
                       "junk": ["sugar", "fried", "fizzy", "salty", "fatty", "ultra"]},
        "accessRule": {"type": "anyActiveLock", "minOriginalSeconds": 0, "minRemainingSeconds": 0, "aggregation": "sum", "minimumTokens": "TBD"},
        "bags": out_bags,
    }
    for p in (os.path.join(os.path.dirname(ROOT), "PIKKO-BAGS.json"), os.path.join(ROOT, "src", "data", "bags.json")):
        with open(p, "w", encoding="utf-8") as fh:
            json.dump(doc, fh, ensure_ascii=False, indent=1)
        print("wrote", p)
    print(len(out_bags), "bags,", sum(len(b["foods"]) for b in out_bags), "foods")


if __name__ == "__main__":
    main()
